import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

/** Time per processing step. */
const STEP_MS = 100;
/** Total attempts per job, including the first. */
const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried (within the 250 ms to 2 s allowed). */
const RETRY_DELAY_MS = 500;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;

const db = openDatabase();
let stopping = false;

const writeHeartbeat = db.prepare(
  "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
);
const deleteHeartbeat = db.prepare("DELETE FROM heartbeats WHERE name = 'worker'");
const nextQueued = db.prepare("SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq LIMIT 1");
const markRunning = db.prepare("UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ?");
const markProgress = db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?');
const markCompleted = db.prepare(
  "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
);
const markFailed = db.prepare(
  "UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = 'transient failure', updated_at = ? WHERE id = ?",
);
const markRetry = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ?",
);
const requeueRunning = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE status = 'running'",
);

function beat(): void {
  try {
    writeHeartbeat.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed', e);
  }
}

/** Runs one attempt of a job. Returns early, leaving the job `running`, if the worker is stopping. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts + 1;
  markRunning.run(attempt, new Date().toISOString(), job.id);

  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return;
    const now = new Date().toISOString();
    if (attempt >= MAX_ATTEMPTS) {
      markFailed.run(now, job.id);
      console.log(`job ${job.id} failed after ${attempt} attempts`);
    } else {
      markRetry.run(Date.now() + RETRY_DELAY_MS, now, job.id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    markProgress.run(step, new Date().toISOString(), job.id);
  }
  markCompleted.run(job.input.toUpperCase(), new Date().toISOString(), job.id);
  console.log(`job ${job.id} completed on attempt ${attempt}`);
}

beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

// This worker is the only one, so any job still marked running was interrupted by a previous exit.
requeueRunning.run(new Date().toISOString());

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

console.log('worker started');
while (!stopping) {
  try {
    const job = nextQueued.get(Date.now()) as unknown as JobRow | undefined;
    if (job) await runAttempt(job);
    else await sleep(IDLE_POLL_MS);
  } catch (e) {
    console.error('worker error', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
requeueRunning.run(new Date().toISOString());
deleteHeartbeat.run();
db.close();
console.log('worker stopped');
process.exit(0);

